<?php
if (!defined('ABSPATH')) exit;
function gim_material_plan($job_id){ global $wpdb; return $wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('materials').' WHERE job_id=%d',$job_id)); }
function gim_set_material_plan($job_id,$quoted_pence,$required=true){ global $wpdb; $old=gim_material_plan($job_id); $data=['job_id'=>$job_id,'status'=>$required?'awaiting_invoice':'not_required','quoted_pence'=>max(0,(int)$quoted_pence),'created_at'=>$old?$old->created_at:gim_now(),'updated_at'=>gim_now()]; if($old)$wpdb->update(gim_table('materials'),$data,['id'=>$old->id]); else $wpdb->insert(gim_table('materials'),$data); }
function gim_invoice_intelligence($job_id,$lines,$actual_pence){ $find=[];$score=0; $plan=gim_material_plan($job_id); if(!$plan)return ['decision'=>'PASS','score'=>0,'findings'=>[]]; $quoted=(int)$plan->quoted_pence; if($actual_pence<0){$find[]=['severity'=>'BLOCK','code'=>'NEGATIVE_TOTAL'];$score+=100;} if($quoted>0&&$actual_pence>$quoted*1.5){$find[]=['severity'=>'REVIEW','code'=>'ACTUAL_ABOVE_QUOTE_50'];$score+=35;} if(!$lines){$find[]=['severity'=>'REVIEW','code'=>'NO_EXTRACTED_LINES'];$score+=15;}
 $bench=defined('GIM_UK_MATERIAL_BENCHMARK_FILE')&&file_exists(GIM_UK_MATERIAL_BENCHMARK_FILE)?json_decode(file_get_contents(GIM_UK_MATERIAL_BENCHMARK_FILE),true):[]; foreach((array)$lines as $line){ $name=strtolower(trim($line['name']??'')); $qty=(float)($line['quantity']??0); $unit=(int)($line['unit_pence']??0); if($qty<=0||$unit<0){$find[]=['severity'=>'BLOCK','code'=>'INVALID_LINE'];$score+=50;continue;} if(isset($bench[$name])){ $max=(int)($bench[$name]['max_pence']??0); if($max&&$unit>$max*1.35){$find[]=['severity'=>'REVIEW','code'=>'UK_PRICE_OUTLIER','item'=>$name];$score+=20;} } else $find[]=['severity'=>'INFO','code'=>'UK_REFERENCE_UNAVAILABLE','item'=>$name]; }
 $decision=$score>=70?'BLOCK':($score>=20?'REVIEW_REQUIRED':'PASS'); return ['decision'=>$decision,'score'=>min(100,$score),'findings'=>$find]; }
function gim_upload_material_invoice($job_id,$provider_user_id,$actual_pence,$lines=[]){ global $wpdb; $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job||!gim_job_owned_by_provider($job,$provider_user_id))return new WP_Error('forbidden','Forbidden.'); $up=gim_secure_upload('invoice','materials/'.$job->reference); if(is_wp_error($up))return $up; $ai=gim_invoice_intelligence($job_id,$lines,$actual_pence); $plan=gim_material_plan($job_id); if(!$plan)gim_set_material_plan($job_id,0,true); $wpdb->update(gim_table('materials'),['status'=>$ai['decision']==='PASS'?'ai_passed':($ai['decision']==='BLOCK'?'ai_blocked':'ai_review_required'),'actual_pence'=>$actual_pence,'invoice_file'=>$up['path'],'invoice_hash'=>$up['hash'],'lines_json'=>gim_json($lines),'ai_decision'=>$ai['decision'],'ai_score'=>$ai['score'],'ai_findings_json'=>gim_json($ai['findings']),'updated_at'=>gim_now()],['job_id'=>$job_id]); gim_audit('materials.invoice_checked','job',$job->reference,$ai); return $ai; }
